window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ea91982acf039eb8"]={"versions": [{"id": "FIG-ea91982acf039eb8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (UML-basiertes Kompositions- und Strukturmodell gemäß AUTOSAR Virtual Function Bus / Software-Component Modeling Guide).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des hierarchischen Kapselungs- und Typ-Prototyp-Prinzips im AUTOSAR-Metamodell (M2). Demonstration, wie ein übergeordneter Kompositionstyp (<code>CompositionSwComponentType</code>) interne Komponenten-Instanzen (<code>SwComponentPrototype</code>) kapselt und deren Schnittstellen über Delegations-Konnektoren an die äußere Systemgrenze exponiert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>KeyPad</code> (<code>SwComponentType</code> / <code>CompositionSwComponentType</code>):</strong></li>\n<li>Äußerer hierarchischer Kapselungsrahmen.</li>\n<li>Fungiert als abstrakter Kompositionstyp zur logischen Gruppierung von Sub-Funktionen im VFB.</li>\n<li><strong><code>KeyPadMgr</code> (<code>SwComponentPrototype</code>):</strong></li>\n<li>Innerhalb der Komposition instanziierter Prototyp (<code>contextComponent</code>).</li>\n<li>Realisiert die eigentliche Anwendungslogik und referenziert typisierend einen zugrundeliegenden atomaren Komponententyp (<code>AtomicSwComponentType</code>, z. B. <code>ApplicationSwComponentType</code>).</li>\n<li><strong>Ports (<code>PPortPrototype</code>):</strong></li>\n<li>Alle dargestellten Ports sind Provided-Ports (Symbol: Quadrat mit ausgehender Pfeil-/Trapezspitze):</li>\n<li><code>DrvrDoorKeypad</code> (innen): <code>PPortPrototype</code> des <code>KeyPadMgr</code>-Prototyps.</li>\n<li><code>DrvrDoorKeypad</code> (außen): <code>PPortPrototype</code> der umschließenden <code>KeyPad</code>-Komposition.</li>\n<li><code>KeyPadOfLidRe</code> (außen): Weiterer <code>PPortPrototype</code> der <code>KeyPad</code>-Komposition (in dieser Ansicht noch unbeschaltet).</li>\n<li><strong>Konnektor (<code>DelegationSwConnector</code>):</strong></li>\n<li>Verbindet den inneren P-Port <code>KeyPadMgr.DrvrDoorKeypad</code> direkt mit dem äußeren Kompositions-Port <code>KeyPad.DrvrDoorKeypad</code>.</li>\n<li>Kardinalität: 1:1-Delegationspfad für Provider-Ports (<code>outerPort</code> $\\rightarrow$ <code>innerPort</code> via <code>SwComponentPrototypeRef</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Strukturmodell:</strong> Kein sequenzielles Laufzeitverhalten oder Task-Scheduling dargestellt.</li>\n<li><strong>VFB-Delegationssemantik:</strong></li>\n<li>Der Delegationskonnektor stellt ein reines Entwurfszeit-Konstrukt ohne eigenen Laufzeit-Overhead dar.</li>\n<li>Es existiert kein Puffer-, Queue- oder Task-Kontext auf Ebene des <code>DelegationSwConnector</code>.</li>\n<li>Datenübertragungen (z. B. Sender-Receiver) bzw. Operationen (Client-Server) werden transparent durchgereicht.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine RTE-Generierung für Kompositionen:</strong></li>\n<li>Die RTE generiert ausschließlich Code für atomare Software-Komponenten (<code>AtomicSwComponentType</code>). Für <code>KeyPad</code> existiert zur Laufzeit weder ein C-Modul noch ein Instanz-Deskriptor.</li>\n<li><strong>Schnittstellen-Vertrag (<code>PortInterface</code>):</strong></li>\n<li>Der innere und der äußere Port <code>DrvrDoorKeypad</code> müssen identische <code>PortInterface</code>-Definitionen (z. B. identisches <code>SenderReceiverInterface</code> oder <code>ClientServerInterface</code>) referenzieren; Typ-Inkompatibilitäten führen zum Abbruch bei der Validierung des ARXML-Modells.</li>\n<li><strong>Flattening beim System-Build:</strong></li>\n<li>Vor der RTE- und BSW-Generierung wird die Kompositionshierarchie im System-Extract vollständig aufgelöst (Flattening). Der Delegationskonnektor verschmilzt mit dem späteren <code>AssemblySwConnector</code> des Konsumenten zu einem direkten Kommunikationspfad (RTE-Puffer, Shared Memory oder COM-Signal-Mapping).</li>\n<li><strong>Unvollständige Komposition (<code>KeyPadOfLidRe</code>):</strong></li>\n<li>Ein unbeschalteter äußerer Port muss vor dem finalen System-Mapping entweder mit einem weiteren internen Prototyp-Port verbunden oder als ungenutzter Schnittstellen-Endpunkt im System-Extract validiert werden.</li>\n</ul>"}, {"id": "FIG-38381a3e87f4cd9c", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (UML-basiertes Kompositions- und Strukturmodell gemäß AUTOSAR Virtual Function Bus / Software-Component Modeling Guide).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des hierarchischen Kapselungs- und Typ-Prototyp-Prinzips im AUTOSAR-Metamodell (M2). Demonstration, wie ein übergeordneter Kompositionstyp (<code>CompositionSwComponentType</code>) interne Komponenten-Instanzen (<code>SwComponentPrototype</code>) kapselt und deren Schnittstellen über Delegations-Konnektoren an die äußere Systemgrenze exponiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>KeyPad</code> (<code>SwComponentType</code> / <code>CompositionSwComponentType</code>):</strong></li>\n<li>Äußerer hierarchischer Kapselungsrahmen.</li>\n<li>Fungiert als abstrakter Kompositionstyp zur logischen Gruppierung von Sub-Funktionen im VFB.</li>\n<li><strong><code>KeyPadMgr</code> (<code>SwComponentPrototype</code>):</strong></li>\n<li>Innerhalb der Komposition instanziierter Prototyp (<code>contextComponent</code>).</li>\n<li>Realisiert die eigentliche Anwendungslogik und referenziert typisierend einen zugrundeliegenden atomaren Komponententyp (<code>AtomicSwComponentType</code>, z. B. <code>ApplicationSwComponentType</code>).</li>\n<li><strong>Ports (<code>PPortPrototype</code>):</strong></li>\n<li>Alle dargestellten Ports sind Provided-Ports (Symbol: Quadrat mit ausgehender Pfeil-/Trapezspitze):</li>\n<li><code>DrvrDoorKeypad</code> (innen): <code>PPortPrototype</code> des <code>KeyPadMgr</code>-Prototyps.</li>\n<li><code>DrvrDoorKeypad</code> (außen): <code>PPortPrototype</code> der umschließenden <code>KeyPad</code>-Komposition.</li>\n<li><code>KeyPadOfLidRe</code> (außen): Weiterer <code>PPortPrototype</code> der <code>KeyPad</code>-Komposition (in dieser Ansicht noch unbeschaltet).</li>\n<li><strong>Konnektor (<code>DelegationSwConnector</code>):</strong></li>\n<li>Verbindet den inneren P-Port <code>KeyPadMgr.DrvrDoorKeypad</code> direkt mit dem äußeren Kompositions-Port <code>KeyPad.DrvrDoorKeypad</code>.</li>\n<li>Kardinalität: 1:1-Delegationspfad für Provider-Ports (<code>outerPort</code> $\\rightarrow$ <code>innerPort</code> via <code>SwComponentPrototypeRef</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Strukturmodell:</strong> Kein sequenzielles Laufzeitverhalten oder Task-Scheduling dargestellt.</li>\n<li><strong>VFB-Delegationssemantik:</strong></li>\n<li>Der Delegationskonnektor stellt ein reines Entwurfszeit-Konstrukt ohne eigenen Laufzeit-Overhead dar.</li>\n<li>Es existiert kein Puffer-, Queue- oder Task-Kontext auf Ebene des <code>DelegationSwConnector</code>.</li>\n<li>Datenübertragungen (z. B. Sender-Receiver) bzw. Operationen (Client-Server) werden transparent durchgereicht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine RTE-Generierung für Kompositionen:</strong></li>\n<li>Die RTE generiert ausschließlich Code für atomare Software-Komponenten (<code>AtomicSwComponentType</code>). Für <code>KeyPad</code> existiert zur Laufzeit weder ein C-Modul noch ein Instanz-Deskriptor.</li>\n<li><strong>Schnittstellen-Vertrag (<code>PortInterface</code>):</strong></li>\n<li>Der innere und der äußere Port <code>DrvrDoorKeypad</code> müssen identische <code>PortInterface</code>-Definitionen (z. B. identisches <code>SenderReceiverInterface</code> oder <code>ClientServerInterface</code>) referenzieren; Typ-Inkompatibilitäten führen zum Abbruch bei der Validierung des ARXML-Modells.</li>\n<li><strong>Flattening beim System-Build:</strong></li>\n<li>Vor der RTE- und BSW-Generierung wird die Kompositionshierarchie im System-Extract vollständig aufgelöst (Flattening). Der Delegationskonnektor verschmilzt mit dem späteren <code>AssemblySwConnector</code> des Konsumenten zu einem direkten Kommunikationspfad (RTE-Puffer, Shared Memory oder COM-Signal-Mapping).</li>\n<li><strong>Unvollständige Komposition (<code>KeyPadOfLidRe</code>):</strong></li>\n<li>Ein unbeschalteter äußerer Port muss vor dem finalen System-Mapping entweder mit einem weiteren internen Prototyp-Port verbunden oder als ungenutzter Schnittstellen-Endpunkt im System-Extract validiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-ea91982acf039eb8", "to": "FIG-38381a3e87f4cd9c", "fr": "R4.0.3", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
